export function getChangelog(): Array<{ version: string; items: string[] }> {
  return CHANGELOG.map(g => ({ version: g.version, items: g.items.map(i => i[currentLang]) }))
}

// Nombre localizado de un movimiento: en inglés usa el nombre de PokeAPI en
// inglés (guardado en move.enName); en español usa el nombre en español.
export function moveName(move: { name: string; enName?: string }): string {
  if (currentLang === 'en') return move.enName || move.name
  return move.name
}

const STATUS_TEXT: Record<string, { es: string; en: string }> = {
  burn: { es: '🔥 Quemado', en: '🔥 Burned' },
  poison: { es: '☠️ Envenenado', en: '☠️ Poisoned' },
  paralysis: { es: '⚡ Paralizado', en: '⚡ Paralyzed' },
  freeze: { es: '🧊 Congelado', en: '🧊 Frozen' },
  sleep: { es: '💤 Dormido', en: '💤 Asleep' },
  confusion: { es: '💫 Confundido', en: '💫 Confused' },
  flinch: { es: '❕ Aturdido', en: '❕ Flinching' },
  leechSeed: { es: '🌱 Drenado', en: '🌱 Drained' },
}

export function statusLabel(type: string): string {
  const e = STATUS_TEXT[type]
  return e ? e[currentLang] : type
}

const STATUS_APPLIED_KEY: Record<string, string> = {
  burn: 'b.gotBurn',
  poison: 'b.gotPoison',
  paralysis: 'b.gotParalysis',
  freeze: 'b.gotFreeze',
  sleep: 'b.gotSleep',
  confusion: 'b.gotConfusion',
  flinch: 'b.gotFlinch',
}

export function statusAppliedLine(name: string, type: string): string {
  const key = STATUS_APPLIED_KEY[type]
  return key ? t(key, { name }) : `${name} → ${statusLabel(type)}`
}

